  array['English','Kannada','Hindi']::text[], array['online','academy','blended']::text[], 'Telecaller Level 1', 12, false, true, true,
  'A 2-week, 74-hour programme building listening, accurate information, clean data entry and legal compliance for the first voice of VTIARA.', 'The telecaller is the first voice of VTIARA; one honest, warm call turns an enquiry into a safe first visit. Over 2 weeks (16 hours of Common Core plus 58 telecaller hours), then 3 days of monitored live calls, you learn patient communication and voice, treatment knowledge, six call flows, CRM use, ethical objection handling, compliance and scored mock calls.', 'New telecallers who handle enquiries, appointment booking, follow-up and reminders.', array['12th pass or graduate','Clear spoken English plus the local language of the market','Typing and basic computer skills','Voice and listening test']::text[], array['Sound warm, clear and calm, and listen before speaking','Explain each treatment in simple, approved words and know what not to say','Follow the six call flows from opening to close','Record every call outcome accurately in the CRM the same day','Handle objections honestly without pressure','Follow consent, DND and telecom commercial-communication rules']::text[], array['80% or higher on the knowledge test','Mock-call average of 85% with no critical error','3 days of monitored live calls reviewed']::text[], '{"knowledge_pct":80,"mock_call_pct":85,"compliance":true,"monitored_calls":true}'::jsonb) on conflict (id) do nothing;
